            current_srid = self.__class__.__name__.split('_')[-1]
            if current_srid == target_srid:
                return self
            elif (current_srid, target_srid) in srid_map:
                new_fields = {field: srid_map[(current_srid, target_srid)](getattr(self, field)) for field in fields}
