import os
import subprocess

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if os.name == 'nt':
        cmd = list(cmd)
        if cmd[0].startswith('#!'):
            shebang = cmd[0][2:].strip()
            try:
                script_path, *args = subprocess.run(['where', shebang], capture_output=True, text=True, check=True).stdout.strip().splitlines()
                cmd[0] = os.path.abspath(script_path)
            except subprocess.CalledProcessError:
                pass
    return tuple(cmd)
