def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def wrapper(func):
        cache = {}
        cache_info = {
            'hits': 0,
            'misses': 0,
            'maxsize': maxsize,
            'currsize': 0,
        }

        def cache_get(key):
            try:
                record = cache[key]
                if record[1] >= timer():
                    cache_info['hits'] += 1
                    return record[0]
            except KeyError:
                pass
            cache_info['misses'] += 1
            return None

        def cache_set(key, value):
            if key in cache:
                record = cache[key]
                record[0] = value
                record[1] = timer() + ttl
            else:
                if cache_info['currsize'] < cache_info['maxsize']:
                    cache[key] = [value, timer() + ttl]
                    cache_info['currsize'] += 1
                else:
                    oldest_key = min(cache, key=lambda k: cache[k][1])
                    cache.pop(oldest_key)
                    cache[key] = [value, timer() + ttl]

        @wraps(func)
        def memoized_func(*args, **kwargs):
            if typed:
                key = (func, args, tuple(sorted(kwargs.items())))
            else:
                key = (func, tuple(args), frozenset(kwargs.items()))
            value = cache_get(key)
            if value is not None:
                return value
            value = func(*args, **kwargs)
            cache_set(key, value)
            return value

        memoized_func.cache_info = lambda: cache_info
        memoized_func.cache_clear = lambda: cache.clear()
        return memoized_func

    return wrapper

