            key = (args, tuple(kwargs.items()) if typed else tuple(sorted(kwargs.items())))
            if key in cache:
                cache_info['hits'] += 1
                return cache[key]
            else:
                cache_info['misses'] += 1
                if cache_info['currsize'] < cache_info['maxsize']:
                    cache[key] = func(*args, **kwargs)
                    cache_info['currsize'] += 1
                else:
                    oldest_key = next(iter(cache))
                    del cache[oldest_key]
                    cache[key] = func(*args, **kwargs)
                return cache[key]

        def cache_clear():
            nonlocal cache
            cache = {}
            cache_info['currsize'] = 0

        def cache_info():
            return cache_info

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        return wrapper

    return decorator
