def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    from functools import wraps
    from collections import OrderedDict

    class LRUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typized = typed
            self.cache = OrderedDict()
            self.typed_cache = None if not typed else {}

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = args if not self.typed else (func, args, frozenset(kwargs.items()))
                typed_key = None if not self.typed else (func, args, tuple(sorted(kwargs.items())))

                if key in self.cache:
                    self.cache.move_to_end(key)
                    return self.cache[key]
                elif typed_key and typed_key in self.typed_cache:
                    self.typed_cache[typed_key].move_to_end(typed_key)
                    return self.typed_cache[typed_key][typed_key]

                result = func(*args, **kwargs)
                if len(self.cache) >= self.maxsize:
                    self.cache.popitem(last=False)
                if self.typed_cache:
                    if len(self.typed_cache) >= self.maxsize:
                        self.typed_cache.popitem(last=False)
                    if typed_key:
                        self.typed_cache[typed_key] = OrderedDict()
                        self.typed_cache[typed_key][typed_key] = result
                else:
                    self.cache[key] = result

                return result

            return wrapper

    return LRUCache(maxsize, typed).cache

