def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self frequencies = {}
            self.access_count = 0

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = (func, args, tuple(kwargs.items())) if self.typed else (func, args, frozenset(kwargs.items()))
                if key not in self.cache:
                    self.cache[key] = func(*args, **kwargs)
                    self.frequencies[key] = 0
                self.access_count += 1
                self.frequencies[key] += 1
                self.evict()
                return self.cache[key]
            return wrapper

        def evict(self):
            if len(self.cache) > self.maxsize:
                least_frequently_used = min(self.frequencies, key=self.frequencies.get)
                del self.cache[least_frequently_used]
                del self.frequencies[least_frequently_used]

    return LFUCache(maxsize, typed).__call__
