def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Sort classes by their hierarchy depth
    classes.sort(key=lambda cls: cls.__mro__.index(object))

    minimal_set = set()

    while classes:
        current_class = classes.pop(0)
        if all(current_class not in cls.__mro__ for cls in minimal_set):
            minimal_set.add(current_class)

    # Return a sorted list of the minimal base classes
    return sorted(minimal_set, key=lambda cls: cls.__mro__.index(object))

