def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Create a set to store the minimal bases
    minimal_bases = set()

    # Iterate over each class in the input list
    for cls in classes:
        # Check if the class is not a subclass of any other class in the list
        if all(not issubclass(cls, c) for c in classes if c != cls):
            minimal_bases.add(cls)

    # Return the list of minimal base classes
    return list(minimal_bases)

