def difference(d1, d2, level=-1):
    if level == -1:
        return difference_recursive(d1, d2)
    elif level == 1:
        return {k: v for k, v in d1.items() if k not in d2 or v != d2[k]}
    else:
        diff = {}
        for k, v in d1.items():
            if k not in d2:
                diff[k] = v
            else:
                sub_diff = difference(v, d2[k], level - 1)
                if sub_diff:
                    diff[k] = sub_diff
        return diff

def difference_recursive(d1, d2):
    return {k: (difference_recursive(v1, v2) if isinstance(v1, dict) and isinstance(v2, dict) else v1)
            for k, v1 in d1.items()
            if k not in d2 or v1 != d2[k]}

