import re
from typing import Dict, Any, List

class ValidationError(Exception):
    def __init__(self, messages: List[Dict[str, str]]):
        self.messages = messages
        super().__init__(', '.join(f'{key}: {message}' for key, message in messages))

def _validate_labels(labels: Dict[str, Any]) -> None:
    """
    Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression.
    """

    regex_key = re.compile(r'^[a-zA-Z0-9_]+$')
    regex_value = re.compile(r'^[a-zA-Z0-9_]+$')

    errors = []

    for key, value in labels.items():
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, str) and not isinstance(v, bytes):
                    errors.append({str(v): 'expected string or bytes-like object'})
        else:
            if not isinstance(value, str) and not isinstance(value, bytes):
                errors.append({str(key): 'expected string or bytes-like object'})

        if not regex_key.match(str(key)):
            errors.append({str(key): "Label key '{}' does not match the regex pattern".format(key)})

        if not regex_value.match(str(value)):
            errors.append({str(key): "Label value '{}' does not match the regex pattern".format(value)})

    if errors:
        raise ValidationError(errors)
