def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    assert isinstance(prior, InventoryValidator)

    # Check if the prior version is lexicographically smaller than the current version
    if self.version >= prior.version:
        raise ValueError("Prior version must be earlier than the current version")

    # Check if the prior inventory has all the items of the current inventory
    for item in self.items:
        if item not in prior.items:
            raise ValueError("Prior version must contain all items of the current version")

    # Check if the prior inventory has the same item types as the current inventory
    if set(self.items.keys()) != set(prior.items.keys()):
        raise ValueError("Prior version must have the same item types as the current version")

    # Check if the prior inventory has the same item values as the current inventory
    for item_type, item_values in self.items.items():
        for value in item_values:
            if value not in prior.items[item_type]:
                raise ValueError("Prior version must have the same item values as the current version")

