def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.endswith('B'):
        return int(size[:-1])
    elif size.endswith('K'):
        return int(size[:-1]) * 1000
    elif size.endswith('M'):
        return int(size[:-1]) * 1000000
    elif size.endswith('G'):
        return int(size[:-1]) * 1000000000
    elif size.endswith('T'):
        return int(size[:-1]) * 1000000000000
    else:
        raise ValueError("Invalid size format")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.endswith('B') or size.isdigit():
        return int(size.replace('B', ''))
    elif size.endswith('K'):
        return int(float(size[:-1]) * 1000)
    elif size.endswith('M'):
        return int(float(size[:-1]) * 1000000)
    elif size.endswith('G'):
        return int(float(size[:-1]) * 1024 * 1024 * 1024)
    elif size.endswith('T'):
        return int(float(size[:-1]) * 1024 * 1024 * 1024 * 1024)
    else:
        raise ValueError(f"Unsupported size format: {size}")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """

    size = size.upper()
    if size.endswith('B'):
        size = size[:-1]
    if ',' in size:
        size = size.replace(',', '.')

    if size.endswith('K'):
        value = float(size[:-1]) * 1024
    elif size.endswith('M'):
        value = float(size[:-1]) * 1024 * 1024
    elif size.endswith('G'):
        value = float(size[:-1]) * 1024 * 1024 * 1024
    elif size.endswith('T'):
        value = float(size[:-1]) * 1024 * 1024 * 1024 * 1024
    elif size.endswith('P'):
        value = float(size[:-1]) * 1024 * 1024 * 1024 * 1024 * 1024
    else:
        value = float(size)

    return round(value)

