def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number == 0:
        return alphabet[0]

    result = []
    base = len(alphabet)

    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    if padding and len(result) < padding:
        result += [alphabet[0]] * (padding - len(result))

    return ''.join(reversed(result))

