def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''

    import json
    from logging import LogRecord, getLogger, StreamHandler, Formatter

    log = getLogger(__name__)
    handler = StreamHandler()
    handler.setFormatter(Formatter('%(levelname)s: %(message)s'))
    log.addHandler(handler)

    configs = {}
    errors = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                if overrides:
                    config.update(overrides)
                if resolve_env:
                    config = resolve_environment_variables(config)
                configs[filename] = config
        except FileNotFoundError:
            log.error(f"Configuration file not found: {filename}")
            errors.append(LogRecord('load_configurations', 'ERROR', filename, 1, f"Configuration file not found: {filename}", [], None))
        except json.JSONDecodeError:
            log.error(f"Invalid JSON in configuration file: {filename}")
            errors.append(LogRecord('load_configurations', 'ERROR', filename, 1, f"Invalid JSON in configuration file: {filename}", [], None))
        except Exception as e:
            log.error(f"Error processing configuration file: {filename}", exc_info=True)
            errors.append(LogRecord('load_configurations', 'ERROR', filename, 1, f"Error processing configuration file: {filename}", [], None))

    return configs, errors

def resolve_environment_variables(config):
    import os
    import re

    env_var_regex = re.compile(r'\$\{([a-zA-Z0-9_]+)\}')

    def replace_env_vars(match):
        env_var = match.group(1)
        return os.getenv(env_var, match.group(0))

    json_str = json.dumps(config)
    resolved_json_str = env_var_regex.sub(replace_env_vars, json_str)
    return json.loads(resolved_json_str)

