def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """

    tags = set()
    result = []

    in_code_block = False
    tag = []
    for char in text:
        if char == '`' and not in_code_block and not tag:
            in_code_block = True
        elif char == '`' and in_code_block and not tag:
            in_code_block = False
        elif char == '<' and not in_code_block:
            tag.append(char)
        elif char == '>' and not in_code_block and tag:
            tag.append(char)
            tags.add(''.join(tag))
            tag = []
        elif char != '<' and char != '>' and not in_code_block and tag:
            tag.append(char)
        elif not in_code_block:
            result.append(char)

    result_text = ''.join(result)

    if replacer:
        for tag in tags:
            result_text = result_text.replace(tag, replacer(tag))

    return tags, result_text

