def find_tags(text: str, replacer: Optional[Callable[[str], str]] = None) -> Tuple[Set[str], str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    result = []
    for line in text.split('\n'):
        start = 0
        while start < len(line):
            if line[start:start+3] == '```':
                in_code_block = not in_code_block
                start += 3
            elif not in_code_block:
                match = re.search(r'\b\w+\b', line[start:])
                if match:
                    tag = match.group(0)
                    if tag.startswith('tag:'):
                        tags.add(tag[4:])
                        if replacer:
                            new_tag = replacer(tag[4:])
                            line = line[:start + match.start()] + new_tag + line[start + match.end():]
                        start += len(new_tag)
                    else:
                        start += match.end()
                else:
                    start += 1
            else:
                start += 1
        result.append(line)
    return tags, '\n'.join(result)
