            new_text.append(line)
        else:
            words = line.split()
            for word in words:
                if word.startswith('<') and word.endswith('>'):
                    tag = word[1:-1]
                    tags.add(tag)
                    if replacer:
                        word = replacer(tag)
                new_text.append(word)
            new_text.append('\n')

    return tags, ' '.join(new_text)
