import re

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    # Regular expression to find URLs and email addresses
    pattern = re.compile(r'(\bhttps?://\S+|\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b)')

    def linkify(match):
        url = match.group(1)
        if url.startswith('http') or url.startswith('https'):
            return f'<a href="{url}" class="link">{url}</a>'
        elif '@' in url:
            return f'<a href="mailto:{url}" class="email">{url}</a>'

    return pattern.sub(linkify, text)
