    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('--'):
            control_args[arg[2:]] = True
        elif '=' in arg:
            key, value = arg.split('=', 1)
            if key.startswith('nested_'):
                nested_args[key[9:]] = value
            elif key.startswith('custom_'):
                custom_args[key[7:]] = value
            else:
                nested_args[key] = value
        else:
            nested_args[arg] = True

    return control_args, nested_args, custom_args

