    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    # Define type mappings for command-line arguments
    type_mappings = {
        'main': {
            'integer_arg': int,
            'float_arg': float,
            'boolean_arg': lambda x: x.lower() in ['true', '1'],
        },
        'virsh': {
            'domain_id': int,
            'memory_size': lambda x: float(x.replace('M', '')) * 1024 * 1024,
        },
        # Add more mappings for other commands as needed
    }

    # Get the specific type mappings for the provided parser_name
    specific_mappings = type_mappings.get(parser_name, {})

    # Iterate over the values_dict and cast the arguments to the correct types
    for key, value in values_dict.items():
        # Check if the key has a specific type mapping
        if key in specific_mappings:
            # Cast the value to the specified type
            values_dict[key] = specific_mappings[key](value)
        else:
            # If no specific type mapping, keep the value as a string
            values_dict[key] = value

