def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Define a dictionary to map parser names to the expected types for their arguments
    parser_types = {
        'main': {
            'argument1': int,
            'argument2': float,
            'argument3': bool
        },
        'virsh': {
            'argument1': str,
            'argument2': list,
            'argument3': dict
        },
        'ospd': {
            'argument1': int,
            'argument2': str,
            'argument3': float
        }
    }

    # Check if the parser_name is valid
    if parser_name not in parser_types:
        raise ValueError(f"Unknown parser name: {parser_name}")

    # Convert the arguments to their expected types
    for key, value in values_dict.items():
        if key in parser_types[parser_name]:
            values_dict[key] = parser_types[parser_name][key](value)
